const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

const results = [];
const now = Date.now();

// 1. Fetch all open conversations with pagination
let allOpenConvs = [];
try {
  let page = 1;
  while (page <= 10) {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/conversations?status=open&page=${page}`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    const payload = resp.data?.payload || [];
    if (payload.length === 0) break;
    allOpenConvs.push(...payload);
    if (payload.length < 25) break;
    page++;
  }
} catch (e) {}

// Deduplicate conversations by ID
const convMap = new Map();
for (const c of allOpenConvs) {
  if (c && c.id) convMap.set(c.id, c);
}

for (const [convId, conv] of convMap.entries()) {
  const currentLabels = Array.isArray(conv.labels) ? conv.labels : [];

  // Fetch messages to determine the last customer message timestamp
  let msgs = [];
  try {
    const msgResp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/conversations/${convId}/messages`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    msgs = msgResp.payload || [];
  } catch (e) {
    continue;
  }

  // Customer incoming messages: message_type === 0 (or 'incoming') and not private
  const customerMsgs = msgs.filter(m => (m.message_type === 0 || m.message_type === 'incoming') && m.private !== true);

  let lastCustomerTimeMs = 0;
  if (customerMsgs.length > 0) {
    const lastMsg = customerMsgs[customerMsgs.length - 1];
    const ts = Number(lastMsg.created_at || lastMsg.created_at_epoch || 0);
    lastCustomerTimeMs = ts > 1e11 ? ts : ts * 1000;
  } else {
    const ts = Number(conv.created_at || conv.last_activity_at || 0);
    lastCustomerTimeMs = ts > 1e11 ? ts : ts * 1000;
  }

  const elapsedHours = (now - lastCustomerTimeMs) / (1000 * 3600);

  // If 48+ hours have elapsed without any customer message:
  if (elapsedHours >= 48) {
    // 1. Remove 'human' label (so future customer messages are handled by AI Agent immediately)
    // 2. Add 'autoclosed' label
    let updatedLabels = currentLabels.filter(l => l !== 'human');
    if (!updatedLabels.includes('autoclosed')) {
      updatedLabels.push('autoclosed');
    }

    // Update labels in Chatwoot
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/labels`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { labels: updatedLabels },
        json: true
      });
    } catch (e) {}

    // Resolve conversation
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/toggle_status`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { status: 'resolved' },
        json: true
      });
    } catch (e) {}

    results.push({
      convId,
      action: 'autoclosed_and_resolved',
      elapsedHours: Math.round(elapsedHours * 10) / 10
    });
  } else {
    results.push({
      convId,
      action: 'waiting',
      elapsedHours: Math.round(elapsedHours * 10) / 10,
      neededHours: 48
    });
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    processed_count: results.length,
    results
  }
}];
